C = dict(id='GL-27', title='Ghost Kitchens', group='Business and Commerce', level=4,
 summary='Plan and run a delivery-only kitchen safely: choose a menu, set up a licensed space, control food safety and cost, and manage orders on delivery apps.',
 outcomes=['Explain the ghost-kitchen model, its risks and its rules.', 'Design a small menu that suits delivery and the kitchen layout.', 'Analyse food cost, prep time and platform commissions.', 'Create a food-safety plan, prep sheets and an order flow.', 'Evaluate sales, ratings and waste after a trial run.'],
 task='Plan and run a 2-week trial of a delivery-only menu from a licensed kitchen with costed recipes, a food-safety plan and order records.',
 cond='Access to a licensed shared or partner kitchen, a thermometer, scales, a spreadsheet, a mentor with food-business experience and a peer circle. About 12 weeks part-time.',
 std='Kitchen licence and registration shown; food-safety plan complete and followed; every dish costed with a target food cost; 90% of orders ready within promised time; waste under 8% of food bought; ratings 4 of 5 or better.',
 who='Cooks, restaurant staff, caterers, food entrepreneurs, students.', req='Basic food-hygiene knowledge helps.',
 safety='Food must be made in premises your food authority accepts, by trained people, with allergens controlled. No selling without the registrations your place requires.',
 mods=[
 ('The model', 'A ghost kitchen sells only through delivery.', ['No dining room; lower rent; many brands can share one kitchen.', 'Risks: platform fees, no walk-in, reputation depends on ratings.', 'Fit: foods that travel well.', 'Rules still apply fully.'], 'Burgers travel; ice cream does not unless packed in cold boxes.', 'Compare ghost kitchen with a cafe on five points.', 'Table with reasons.'),
 ('Menu for delivery', 'Fewer dishes, done well.', ['8 to 12 items with shared ingredients.', 'Test how each dish holds for 30 minutes.', 'Packaging that keeps heat and shape.', 'Allergen list for every dish.'], 'Crispy items go in vented boxes; sauces in separate pots.', 'Draft the menu and test three dishes in transit.', 'Dishes arrive in good condition.'),
 ('Kitchen set-up and licences', 'Space, rules and flow.', ['Layout: receive, store, prep, cook, pack, dispatch.', 'Licence and registration of the premises.', 'Hand-wash, cleaning schedule, pest control.', 'Shared-kitchen agreement.'], 'Raw and ready-to-eat foods kept on separate shelves and boards.', 'Draw the layout and licence list.', 'Flow shows no raw-ready crossing.'),
 ('Food safety plan', 'Prevent harm with controls and records.', ['List each step, its hazards, controls, limits and checks, and the action if a limit is missed.', 'Temperatures: keep cold food below the limit and hot food above it; cook until the centre is safe.', 'Cooling and reheating rules.', 'Logs: temperature, cleaning, deliveries.'], 'Cooked rice cooled quickly and chilled; log shows time and temperature.', 'Write the plan and fill a log for three days.', 'Logs complete and signed.'),
 ('Cost and price', 'Delivery fees reduce margin.', ['Food cost % = ingredient cost / selling price.', 'Platform commission can be a large share of each order: check current terms and include it.', 'Packaging per order.', 'Target margin after all costs.'], 'Dish sells 9.00 (an estimate; check your market); ingredients 2.70 (30%); packaging 0.60; commission 2.25; margin 3.45.', 'Cost every dish.', 'Costs include commission and packaging.'),
 ('Orders and timing', 'Speed and accuracy win ratings.', ['Order screen; accept time; prep time; rider handover.', 'Batch prep for peak hours.', 'Check each bag against the ticket.', 'Track delays and reasons.'], 'Average ready time 14 minutes against 15 promised; 92% on time.', 'Run a 2-day simulation or live pilot.', 'On-time rate calculated.'),
 ('Brand and customers', 'Win repeat orders.', ['Name, photos, description.', 'Handle reviews politely.', 'Small offers that do not hurt margin.', 'Collect consent for direct contact.'], 'A late order gets an apology and a small voucher; rating moves from 3 to 5.', 'Write listing text and three review replies.', 'Honest, plain text.'),
 ('Review and scale', 'Decide whether to grow.', ['Sales, margin, waste, ratings.', 'Cut slow dishes.', 'Check capacity before adding brands.', 'Plan 90 days.'], 'Waste 11%: reduce batch size and prep to forecast.', 'Write the trial report.', 'Report names three changes.')],
 quiz=[('What is a ghost kitchen?', 'A delivery-only kitchen with no dining area.'), ('Food cost % formula?', 'Ingredient cost divided by selling price.'), ('Why separate raw and ready?', 'To prevent cross-contamination.'), ('Why log temperatures?', 'They prove safe handling.'), ('Why test dishes in transit?', 'Delivery changes quality.'), ('What is included in price?', 'Ingredients, packaging, commission, labour, overhead and profit.'), ('Why fewer dishes?', 'Speed, quality and less waste.'), ('What must the premises have?', 'The licence and registration your authority requires.'), ('How reduce waste?', 'Prep to forecast and use shared ingredients.'), ('What to do with allergens?', 'List them for every dish and control cross-contact.')],
 rubric=[('Safety', 'Plan and logs complete', 'Authority feedback acted on'), ('Menu', 'Dishes tested in transit', 'Menu cut by data'), ('Costing', 'All dishes costed', 'Target margin reached'), ('Service', '90% on time', '95% with accurate bags'), ('Review', 'Report with changes', 'Changes tested')],
 jobs=[('Ghost-kitchen cook', 'Prepares delivery orders'), ('Kitchen supervisor', 'Runs flow and safety'), ('Food entrepreneur', 'Launches delivery brands'), ('Order coordinator', 'Manages platforms')],
 next='Box Subscription Services; Marketplace Fulfilment Selling; E-Commerce Growth Marketing.',
 local='Food licences, allergen law and platform rules differ by place: check with your food authority.',
 evidence='Your evidence: model comparison, menu and transit test, layout, food-safety plan and logs, costings, order stats and report.',
 ladder=[('Basics of kitchen hygiene', 'Describe what a ghost kitchen is and how it differs from a restaurant. Notes: look at a delivery app and note which brands share one address in your area. Standard: a short note of the differences.'), ('Awareness', "Describe the licence, hygiene and delivery rules a delivery-only kitchen must meet. Notes: read your local authority's public food-business page. Standard: five rules listed with their source."), ('Foundation', 'Cost three recipes: ingredients, labour, packaging, platform fee and waste, and set prices. Notes: practice prices with currency. Standard: food cost under a stated percentage, with the arithmetic shown.'), ('Practitioner', 'Run a mock service with ten orders: timing, temperature checks, packing and a missed order. Notes: use a licensed kitchen or a model kitchen with a mentor. Standard: every order logged, temperatures recorded.'), ('Specialist', 'Plan and run a two-week trial of a delivery-only menu from a licensed kitchen, with costed recipes, a food-safety plan and order records. Notes: include allergen labelling and complaint handling. Standard: no safety record gaps and gross margin reported.'), ('Advanced', "Run several brands from one kitchen with scheduling, hygiene audits and a platform fee review. Notes: add a brand-level margin report. Standard: audit findings closed and each brand's margin reported."), ('Super expert', 'Set the kitchen-level hygiene, order and platform method for ghost kitchens and teach the managers who use it. Notes: run a food-safety review by the book on a set schedule and file the findings.')])

C['deep'] = dict(mods=[
 ('Thinking delivery-only means lighter rules.', 'The kitchen is inspected like any other; the delivery bag is not a reason to skip checks.', 'Which licence do you hold?'),
 ('A huge menu.', 'Ten dishes sharing eight ingredients cut waste.', 'Which ingredients do dishes share?'),
 ('Raw and ready foods near each other.', 'Colour-coded boards and separate shelves.', 'How do you separate raw from ready?'),
 ('Logs filled in at the end of the day.', 'Temperature log signed at each check time.', 'When do you record?'),
 ('Ignoring commission in the price.', '9.00 dish after 25% commission leaves 6.75 to cover everything.', 'What is the commission?'),
 ('Not testing a bag.', 'A test run shows the sauce spills; use a leakproof pot.', 'What packaging did you change?'),
 ('Replying to reviews with excuses.', 'Apologise, fix, offer a small remedy.', 'How did you answer your worst review?'),
 ('Adding brands before one works.', 'Hold a second brand until waste is under 8%.', 'What is your waste?')],
 gloss=[('Cross-contact', 'Allergen moving between foods.'), ('Hazard control', 'A step that prevents harm.'), ('Commission', 'Fee taken by the platform.'), ('Prep sheet', 'List of what to prepare.'), ('Food cost percent', 'Ingredient cost divided by price.'), ('Dispatch', 'Handing over to the rider.')],
 cases=[('The allergy order', 'A customer says they have a nut allergy.', 'What do you do?', 'Follow the allergen plan: check recipes, separate utensils, label the bag, or decline if you cannot be sure.'),
        ('The fridge fault', 'The fridge reads above the limit.', 'Next?', 'Check food, discard if above limits for too long, record, repair and note the cause.')])
C['deep']['extra'] = [
 ['Check what delivery apps are used locally.', 'Watch for stock-out risk on busy days.'],
 ['Photograph each dish consistently.', 'Write allergen lists on a wall chart.'],
 ['Plan the kitchen for flow, not just space.', 'Keep a cleaning rota.'],
 ['Calibrate thermometers.', 'Train all cooks on the plan.'],
 ['Review packaging cost monthly.', 'Include waste in cost.'],
 ['Pre-pack sides.', 'Check the bag before dispatch.'],
 ['Create a short brand story.', 'Respond to praise too.'],
 ['Track top sellers.', 'Write a lessons list.']]

_ex = ['Burgers travel well; ice cream does not unless packed in cold boxes. The menu keeps burgers and drops ice cream.', 'Ten dishes sharing eight ingredients cut waste; the shopping list has 22 items, not 45.', 'Raw and ready foods sit on separate shelves and boards; the layout shows no crossing from raw to ready.', 'Cooked rice is cooled quickly and chilled; the log shows time and temperature at each check.', 'A 9.00 dish: ingredients 2.70 (30%), packaging 0.60, commission 2.25, margin 3.45.', 'Average ready time 14 minutes against 15 promised; 92% on time.', 'A late order gets an apology and a small voucher; the rating moves from 3 to 5.', 'Waste 11%: reduce batch size and prep to forecast; the next week it falls to 7%.']
_extra = ['Check which delivery apps are used locally.', 'Write allergen lists on a wall chart.', 'Keep a cleaning schedule with signatures.', 'Calibrate thermometers each week.', 'Review packaging costs monthly.', 'Pre-pack sides at quiet times.', 'Check each bag against the ticket.', 'Keep a spare of key ingredients.', 'Take clear photos for each dish.', 'Reply to reviews within a day.', 'Track the top three sellers.', 'Record waste by dish.', 'Check the shared-kitchen agreement every quarter.', 'Train new cooks on the food safety plan.', 'Write a lessons list after the trial.', 'Plan the next 90 days with one change at a time.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Compare three models, a single brand, several brands from one kitchen, and a shared kitchen, using the set-up cost, order volume needed and staffing for each.', 'Estimate the weekly orders needed to break even, for example 120 orders at an average of 14 each with a 30 percent food cost, before you commit money.'], ['Choose dishes that travel well for 30 minutes, test each one in a closed delivery box, and drop any that arrive soggy, cold or separated.', 'Keep the menu to 8 to 12 items built from shared ingredients, so waste falls and the kitchen can prepare orders faster.'], ['Before renting any space, check which permits, registrations and inspections your local authority requires, and keep copies of every document in one folder.', 'Plan a layout with separate zones for raw food, cooked food and packing, a dedicated hand-wash sink and a clear cleaning schedule.'], ['Write a simple food safety plan listing each step from ingredient delivery to rider hand-over, the temperature or time limit for that step, and who checks it.', 'Record fridge and hot-holding temperatures twice daily on a sheet, label all stored food with a use-by date, and act at once on any reading outside the limit.'], ['Cost each dish by adding ingredients, packaging and a share of platform fees, then set prices so that ingredient cost stays near 30 percent of the selling price.', 'Compare your prices with similar nearby kitchens, then test one small increase and watch whether order numbers change over two weeks.'], ['Set a prep time for each dish, for instance 12 minutes, and cap incoming orders per quarter-hour so the kitchen is never overloaded.', 'Time the full cycle from order received to rider hand-off, and review late orders weekly to find whether preparation, packing or pickup causes the delay.'], ['Create a clear name, logo and short description, and use real, well-lit photos of the packed meal exactly as customers will receive it.', 'Reply to every review within a day, thank the positive ones, and log complaints to see which dish or step keeps causing problems.'], ['Review weekly sales by dish, food waste in kilograms and refunds, and remove the two weakest menu items each month.', 'Scale only after four consecutive weeks of on-time orders and steady quality, then add opening hours, a second brand or a new delivery area.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"1": "Salads wilt in a closed bag; they are served with the dressing in a small pot, and the menu keeps salad.", "3": "Cleaning chemicals go on a low shelf away from food, in labelled bins; the inspector sees no mixing of storage.", "4": "Chicken is cooked to the safe core temperature your food authority sets and checked with a probe; the check is written on the log with the time and initials.", "5": "One bowl sells for 8.00 and leaves 2.70 once ingredients (2.80), packaging (0.50) and the app's cut (2.00) are paid.", "6": "Orders are ready in 11 minutes against 12 promised; 88 of 100 are on time, so one cook is moved to the busiest hour.", "7": "A wrong item arrives; the kitchen sends the right one free with a note, and the same customer orders again two days later.", "8": "Orders fall 15% on Tuesday; the Tuesday menu is cut from 14 dishes to 8, which brings waste down from 9% to 6%."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will be able to compare ghost-kitchen models and estimate the weekly orders needed to break even before spending on a lease.', 'You will be able to build a short delivery menu of dishes that survive transit, using shared ingredients to cut waste.', 'You will be able to check local permit needs and plan a kitchen layout that keeps raw food, cooked food and packing apart.', 'You will be able to write a step-by-step food safety plan with temperature limits, labelled stock and daily records.', 'You will be able to cost each dish including platform fees and set prices that protect your margin against delivery commissions.', 'You will be able to set prep times and order caps so the kitchen stays calm and orders leave on time.', 'You will be able to present a delivery-only brand with honest photos and use customer reviews to correct recurring problems.', 'You will be able to decide whether to expand using sales, waste and refund figures rather than hopeful guesses.']
